from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up all devices.
prime_hub = PrimeHub()
color_sensor = ColorSensor(Port.E)
left = Motor(Port.B, Direction.CLOCKWISE)
right = Motor(Port.A, Direction.COUNTERCLOCKWISE)
drive_base = DriveBase(left, right, 56, 114)

# Initialize variables.
target_black = 30
base_speed = 400


# The main program starts here.
drive_base.settings(straight_speed=500)
drive_base.straight(650)
drive_base.turn(100)
print(drive_base.angle())
wait(1000)
drive_base.settings(straight_speed=300)
drive_base.straight(120)
wait(1000)
drive_base.settings(straight_speed=500)
drive_base.straight(-130)
wait(1000)
drive_base.turn(50)
wait(1000)
drive_base.straight(-110)
wait(1000)
drive_base.turn(-65)
# then turn and come back!
wait(3000)
drive_base.turn(30)
wait(3000)
drive_base.straight(90)
wait(3000)
drive_base.turn(100)
wait(3000)
drive_base.straight(750)
